# Read the .env to see what Firecrawl config exists
import os

env_path = os.path.expanduser('~/.hermes/.env')
firecrawl_lines = []
try:
    with open(env_path) as f:
        for line in f:
            if 'FIRECRAWL' in line.upper() or 'FIRE' in line.upper():
                # Redact the value
                if '=' in line:
                    key, val = line.strip().split('=', 1)
                    firecrawl_lines.append(f"{key}=[REDACTED-{len(val)}chars]")
                else:
                    firecrawl_lines.append(line.strip())
except Exception as e:
    firecrawl_lines.append(f"Error: {e}")

for l in firecrawl_lines:
    print(l)

# Also check the firecrawl plugin config
print("\n--- Plugin check ---")
import importlib
try:
    from plugins.web.firecrawl.provider import (
        _get_firecrawl_client,
        _has_direct_firecrawl_config,
        _get_direct_firecrawl_config,
        _get_firecrawl_gateway_url,
    )
    print(f"_has_direct_firecrawl_config: {_has_direct_firecrawl_config()}")
    if _has_direct_firecrawl_config():
        cfg = _get_direct_firecrawl_config()
        print(f"Direct config: api_key={'SET' if cfg.get('api_key') else 'NOT SET'}")
    gw = _get_firecrawl_gateway_url()
    print(f"Gateway URL: {gw}")
except Exception as e:
    print(f"Import error: {e}")
"}

